def evens_first(nums):
    lo, hi = 0, len(nums) - 1
    while True:
        while lo <= hi and nums[lo] % 2 == 0:
            lo += 1
        while lo <= hi and nums[hi] % 2 != 0:
            hi -= 1
        if lo > hi:
            return lo
        nums[lo], nums[hi] = nums[hi], nums[lo]
        lo, hi = lo + 1, hi - 1

