static int evensFirst(int[] nums) {
    int lo = 0, hi = nums.length - 1;
    while (true) {
        while (lo <= hi && nums[lo] % 2 == 0) lo++;
        while (lo <= hi && nums[hi] % 2 != 0) hi--;
        if (lo > hi) return lo;
        int t = nums[lo];
        nums[lo++] = nums[hi];
        nums[hi--] = t;
    }
}

