static int[] threeWay(int[] nums, int pivot) {
    int lt = 0, i = 0, gt = nums.length - 1;
    while (i <= gt) {
        if (nums[i] < pivot) {
            int t = nums[lt]; nums[lt] = nums[i]; nums[i] = t;
            lt++;
            i++;
        } else if (nums[i] > pivot) {
            int t = nums[gt]; nums[gt] = nums[i]; nums[i] = t;
            gt--;
        } else {
            i++;
        }
    }
    return new int[] {lt, gt};
}

